mapper.select:
SELECT * FROM `session_boundary_pair` WHERE `l1_zone` = 'FUZZY' AND `process_status` != 'MANUAL_OVERRIDE'
AND `id` > #{lastId}
AND `l2_verdict` IS NULL
ORDER BY `id` ASC LIMIT #{limit}

SELECT *
FROM `session_boundary_pair`
WHERE `l2_verdict` IS NOT NULL

    AND `has_attachment` = #{hasAttachment}


    AND `process_status` = #{processStatus}


    AND `l2_verdict` = #{l2Verdict}


    AND `l2_confidence` = #{l2Confidence}


    AND (
        `parent_conversation_id` LIKE CONCAT('%', #{keyword}, '%')
        OR `message_a_text` LIKE CONCAT('%', #{keyword}, '%')
        OR `message_b_text` LIKE CONCAT('%', #{keyword}, '%')
        OR `l2_reason` LIKE CONCAT('%', #{keyword}, '%')
    )

ORDER BY `update_time` DESC, `id` ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM `session_boundary_pair`
WHERE `l2_verdict` IS NOT NULL

    AND `has_attachment` = #{hasAttachment}


    AND `process_status` = #{processStatus}


    AND `l2_verdict` = #{l2Verdict}


    AND `l2_confidence` = #{l2Confidence}


    AND (
        `parent_conversation_id` LIKE CONCAT('%', #{keyword}, '%')
        OR `message_a_text` LIKE CONCAT('%', #{keyword}, '%')
        OR `message_b_text` LIKE CONCAT('%', #{keyword}, '%')
        OR `l2_reason` LIKE CONCAT('%', #{keyword}, '%')
    )

SELECT *
FROM `session_boundary_pair`
WHERE `l1_zone` = #{l1Zone}
  AND `l1_score` BETWEEN #{scoreMin} AND #{scoreMax}
ORDER BY `l1_score` DESC

SELECT *
FROM `session_boundary_pair`
WHERE `l1_audit_status` = 'UNCHECKED'

    AND `l1_zone` = #{l1Zone}


    AND `has_attachment` = #{hasAttachment}

ORDER BY `id` ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM `session_boundary_pair`
WHERE `l1_audit_status` = 'UNCHECKED'

    AND `l1_zone` = #{l1Zone}


    AND `has_attachment` = #{hasAttachment}
